+/**
+ * Theoretical use (from sales) against actual use (consume movements) per
+ * item between two days (inclusive); items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const round = (n) => Math.round(n * 1000) / 1000;
+  const rows = new Map();
+  const row = (itemId) => {
+    if (!rows.has(itemId)) rows.set(itemId, { itemId, theoretical: 0, actual: 0 });
+    return rows.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    const day = s.soldAt.slice(0, 10);
+    if (day < from || day > to) continue;
+    const dish = (store.data.dishes ?? []).find((d) => d.id === s.dishId);
+    const recipe = dish && store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe) continue;
+    for (const n of scaled(recipe, s.qty)) row(n.itemId).theoretical += n.qty;
+  }
+  for (const m of store.data.movements) {
+    if (m.type !== "consume") continue;
+    const day = m.at.slice(0, 10);
+    if (day < from || day > to) continue;
+    const batch = store.data.batches.find((b) => b.id === m.batchId);
+    if (batch) row(batch.itemId).actual += m.qty;
+  }
+  return [...rows.values()]
+    .map((r) => ({ itemId: r.itemId, theoretical: round(r.theoretical), actual: round(r.actual), difference: round(r.actual - r.theoretical) }))
+    .filter((r) => r.theoretical > 0 || r.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
